add_filter( 'woocommerce_email_attachments', 'perfectpixel_attach_files_to_emails', 10, 2 );

function perfectpixel_attach_files_to_emails( $attachments, $email_id ) {
	$emails = array_filter( array_map( 'trim', explode( ',', '{{email_attachment_emails}}' ) ) );
	if ( ! in_array( $email_id, $emails, true ) ) {
		return $attachments;
	}
	foreach ( wp_parse_id_list( '{{email_attachment_ids}}' ) as $attachment_id ) {
		$file = get_attached_file( $attachment_id );
		if ( $file && file_exists( $file ) ) {
			$attachments[] = $file;
		}
	}
	return $attachments;
}
